SSE parser:

```js
async function streamChat(payload, onDelta, signal) {
  const res = await fetch(endpoint, {...});
  if (!res.ok) throw new Error(await httpError(res));
  const ct = res.headers.get('content-type') || '';
  if (ct.includes('application/json') || !payload.stream) {
    const data = await res.json();
    onDelta(data.choices[0].message.content || '', true);
    return;
  }
  const reader = res.body.getReader();
  const dec = new TextDecoder();
  let buf = '';
  while (true) {
    const {done, value} = await reader.read();
    if (done) break;
    buf += dec.decode(value, {stream:true});
    let idx;
    while ((idx = buf.indexOf('\n')) !== -1) {
      const line = buf.slice(0, idx).trim(); // watch out for \r
      buf = buf.slice(idx+1);
      if (!line.startsWith('data:')) continue;
      const payloadStr = line.slice(5).trim();
      if (payloadStr === '[DONE]') { buf=''; /* stop */ }
      try {
        const j = JSON.parse(payloadStr);
        const d = j.choices && j.choices[0] && (j.choices[0].delta || j.choices[0].message);
        const c = d && (d.content || d.text || '');
        if (c) onDelta(c, false);
      } catch(e) {}
    }
  }
}
```

