Rendering markdown:

```js
function escapeHtml(s){return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;');}
function inline(s){
  s = s.replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>');
  s = s.replace(/(^|[^*])\*([^*\n]+)\*/g,'$1<em>$2</em>');
  s = s.replace(/`([^`]+)`/g,'<code>$1</code>');
  s = s.replace(/(https?:\/\/[^\s<]+)/g,'<a href="$1" target="_blank" rel="noopener">$1</a>');
  return s;
}
function renderMarkdown(src){
  const lines = src.split(/\r?\n/);
  let html = '', listType = null;
  const closeList = () => { if(listType){ html += `</${listType}>`; listType = null; } };
  for (let raw of lines) {
    const line = raw.trimEnd();
    const t = line.trim();
    if (!t) { closeList(); continue; }
    // headings
    const hm = t.match(/^(#{1,4})\s+(.*)$/);
    if (hm) { closeList(); const lvl = Math.min(hm[1].length+1, 5); html += `<h${lvl}>${inline(escapeHtml(hm[2]))}</h${lvl}>`; continue; }
    // ALL CAPS short line → h4
    if (t.length <= 60 && /^[A-Z0-9 ,&/\-–:()]+$/.test(t) && t === t.toUpperCase() && /[A-Z]/.test(t) && !/^\s*[-*•]/.test(t)) {
      closeList(); html += `<h4>${inline(escapeHtml(t))}</h4>`; continue;
    }
    // bullets
    const bm = t.match(/^[-*•]\s+(.*)$/) || t.match(/^\d+[.)]\s+(.*)$/);
    if (bm) {
      const want = /^[-*•]/.test(t) ? 'ul' : 'ol';
      if (listType !== want) { closeList(); html += `<${want}>`; listType = want; }
      html += `<li>${inline(escapeHtml(bm[1]))}</li>`; continue;
    }
    closeList();
    html += `<p>${inline(escapeHtml(t))}</p>`;
  }
  closeList();
  return html;
}
```

